function payload(){const files=state.files.filter(f=>!f.deletedAt),ids=new Set(files.map(f=>f.id)),groups=[...new Map(files.map(f=>[f.testGroupId,{id:f.testGroupId,sampleId:f.sampleId,name:f.testGroup,number:f.testGroupNumber}])).values()];return {format:'lsv-project',version:3,id:state.id,project:{id:state.id,name:state.name||'LSV项目',createdAt:state.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()},samples:[...new Map(files.map(f=>[f.sampleId,{id:f.sampleId,name:f.sampleName}])).values()],testGroups:groups.map(group=>({...group,...state.testGroups.find(item=>item.id===group.id)})),files:files.map(({deletedAt,...f})=>f),records:Object.fromEntries(Object.entries(state.records).filter(([fileId])=>ids.has(fileId))),eis:state.eis.filter(e=>ids.has(e.fileId)),settings:{reaction:state.reaction,targetCurrentsMa:[10,100,1000],currentTargetBasis:'absolute-current',equilibriumPotentialV_RHE:state.equilibriumPotentialV_RHE,overpotentialFormula:'abs(E_at_target_current - equilibriumPotential)'}};}
